do $$ declare r_id uuid; v1 uuid; v2 uuid; out_unit uuid; ing_id uuid; ing_unit uuid; begin select r.id into r_id from public.recipes r where r.name='TEST ONLY — Vangi Bath Powder Production Recipe' limit 1; if r_id is null then return; end if; select id into v1 from public.recipe_versions where recipe_id=r_id and version_number=1; select base_unit_id into out_unit from public.items where id=(select output_item_id from public.recipes where id=r_id); select id,base_unit_id into ing_id,ing_unit from public.items where item_code='RM-001'; if v1 is null or ing_id is null then return; end if; if not exists(select 1 from public.recipe_versions where recipe_id=r_id and version_number=2) then insert into public.recipe_versions(recipe_id,version_number,expected_output_quantity,output_unit_id,notes,status,effective_from,created_by) select recipe_id,2,expected_output_quantity,output_unit_id,coalesce(notes,'')||' | corrected test ingredient unit','active',current_date,created_by from public.recipe_versions where id=v1 returning id into v2; insert into public.recipe_lines(recipe_version_id,ingredient_item_id,quantity,unit_id,sequence_number,notes) values(v2,ing_id,0.5,ing_unit,1,'Corrected test recipe: 500 g Channa Dal per 1000 g output'); update public.recipe_versions set status='inactive' where id=v1; else select id into v2 from public.recipe_versions where recipe_id=r_id and version_number=2; update public.recipe_versions set status='active' where id=v2; end if; end $$;
